using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using TMPro;using TutorialFramework;using UnityEditor.Events;
[InitializeOnLoad]public static class WindPopupStyleSetup{
 static WindPopupStyleSetup(){EditorApplication.update+=Tick;}static string P(Transform t)=>t?(t.parent?P(t.parent)+"/":"")+t.name:"null";
 static void Tick(){if(!File.Exists("Temp/wind-popup-style.flag")||Application.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Temp/wind-popup-style.flag");try{Run();}catch(Exception e){File.WriteAllText("Temp/WindPopupStyle/error.txt",e.ToString());}}
 static void CopyImage(Image source,Image target){target.sprite=source.sprite;target.type=source.type;target.color=source.color;target.material=source.material;target.preserveAspect=source.preserveAspect;target.pixelsPerUnitMultiplier=source.pixelsPerUnitMultiplier;}
 static void Stretch(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=Vector2.zero;r.localScale=Vector3.one;r.localRotation=Quaternion.identity;}
 static void Run(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty)throw new Exception("Save scene first");var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var reference=all.Single(t=>t.name=="Wire Transparency btn");var button=all.Single(t=>t.name=="Wind Speed Button");var panel=all.Single(t=>t.name=="Wind Speed Panel");if(button.Find("Step Highlight"))throw new Exception("Already styled");var oldCanvas=button.parent.gameObject;
 var icon=button.Find("Wind Icon");var label=button.Find("Label");button.SetParent(reference.parent,false);button.SetSiblingIndex(reference.GetSiblingIndex()+1);var r=(RectTransform)button;var rr=(RectTransform)reference;r.anchorMin=rr.anchorMin;r.anchorMax=rr.anchorMax;r.pivot=rr.pivot;r.localScale=rr.localScale;r.localRotation=rr.localRotation;r.sizeDelta=rr.sizeDelta;r.anchoredPosition=rr.anchoredPosition+Vector2.down*76.2f;
 var image=button.GetComponent<Image>();image.color=Color.clear;image.sprite=null;var b=button.GetComponent<Button>();var rb=reference.GetComponent<Button>();b.colors=rb.colors;b.transition=rb.transition;b.animationTriggers=rb.animationTriggers;var animator=reference.GetComponent<Animator>();if(animator){var own=button.gameObject.AddComponent<Animator>();EditorUtility.CopySerialized(animator,own);}
 var baseText=label.GetComponent<TMP_Text>();baseText.fontSize=10;var lr=(RectTransform)label;lr.anchoredPosition=new Vector2(0,8);lr.sizeDelta=new Vector2(58,14);var ir=(RectTransform)icon;ir.sizeDelta=new Vector2(26,26);ir.anchoredPosition=new Vector2(0,5);
 foreach(var state in new[]{"Normal","Highlighted","Pressed"}){var original=reference.Find(state);if(!original)continue;var copy=UnityEngine.Object.Instantiate(original.gameObject,button,false);copy.name=state;copy.transform.SetAsFirstSibling();var oldIcon=copy.transform.Find("Icon");var tint=oldIcon?oldIcon.GetComponent<Image>().color:Color.white;tint.a=1;if(oldIcon)UnityEngine.Object.DestroyImmediate(oldIcon.gameObject);var stateIcon=state=="Normal"?icon:UnityEngine.Object.Instantiate(icon.gameObject,copy.transform,false).transform;stateIcon.SetParent(copy.transform,false);stateIcon.GetComponent<WindSpeedIconGraphic>().color=tint;var stateLabel=state=="Normal"?label:UnityEngine.Object.Instantiate(label.gameObject,copy.transform,false).transform;stateLabel.SetParent(copy.transform,false);stateLabel.GetComponent<TMP_Text>().color=tint;foreach(var graphic in copy.GetComponentsInChildren<Graphic>(true))graphic.raycastTarget=false;}
 var glow=UnityEngine.Object.Instantiate(reference.Find("Highlighted/Glow").gameObject,button,false);glow.name="Step Highlight";var gr=(RectTransform)glow.transform;gr.anchoredPosition=Vector2.zero;gr.sizeDelta=new Vector2(75,75);var gi=glow.GetComponent<Image>();gi.color=new Color(1,1,1,.9f);gi.raycastTarget=false;foreach(var c in glow.GetComponents<MonoBehaviour>().Where(c=>c&&!(c is Image)))UnityEngine.Object.DestroyImmediate(c);glow.transform.SetAsFirstSibling();glow.SetActive(false);
 var settings=all.First(t=>t.name=="Main Settings Multiple Slider Detached");var bg=settings.Find("Background").GetComponent<Image>();CopyImage(bg,panel.GetComponent<Image>());panel.SetParent(reference.parent.parent,false);var pr=(RectTransform)panel;pr.anchorMin=pr.anchorMax=new Vector2(1,.5f);pr.pivot=new Vector2(1,.5f);pr.anchoredPosition=new Vector2(-110,r.anchoredPosition.y);pr.sizeDelta=new Vector2(330,185);pr.localScale=Vector3.one;pr.localRotation=Quaternion.identity;
 foreach(var name in new[]{"Shadow","Border"}){var source=settings.Find(name);if(!source)continue;var frame=UnityEngine.Object.Instantiate(source.gameObject,panel,false);frame.name=name;Stretch((RectTransform)frame.transform);frame.transform.SetAsFirstSibling();foreach(var g in frame.GetComponentsInChildren<Graphic>(true))g.raycastTarget=false;}
 foreach(var child in panel.GetComponentsInChildren<Button>(true)){var ci=child.GetComponent<Image>();ci.sprite=reference.Find("Normal/Outline").GetComponent<Image>().sprite;ci.type=Image.Type.Sliced;ci.color=new Color(.7843137f,.7843137f,.7843137f,1);child.colors=rb.colors;foreach(var text in child.GetComponentsInChildren<TMP_Text>(true))text.color=new Color(.7843137f,.7843137f,.7843137f,1);}
 var report=new StringBuilder("Wind button: "+P(button)+"\nPanel uses existing Main Settings background/border; right-side button visual states/animator copied.\n");
 foreach(var speed in all.Select(t=>t.GetComponent<WindTurbineSpeedController>()).Where(c=>c&&c.HasWindModel)){var so=new SerializedObject(speed);var board=(StoryboardSteps)so.FindProperty("speedStoryboard").objectReferenceValue;int i=so.FindProperty("speedStepIndex").intValue;var step=board.steps[i];for(int k=step.onStepStart.GetPersistentEventCount()-1;k>=0;k--){var target=step.onStepStart.GetPersistentTarget(k) as GameObject;if(target&&step.onStepStart.GetPersistentMethodName(k)=="SetActive"){report.AppendLine(board.name+" element "+i+" old pointer: "+P(target.transform));target.SetActive(false);UnityEventTools.RemovePersistentListener(step.onStepStart,k);}}
 if(step.interaction is SingleClickInteraction single&&single.marker){report.AppendLine("Marker "+P(single.marker.transform));single.marker.SetActive(false);single.marker=null;EditorUtility.SetDirty(single);}
 UnityEventTools.AddBoolPersistentListener(step.onStepStart,glow.SetActive,true);UnityEventTools.AddBoolPersistentListener(step.onStepEnd,glow.SetActive,false);EditorUtility.SetDirty(board);}
 foreach(var t in button.GetComponentsInChildren<Transform>(true))t.gameObject.layer=reference.gameObject.layer;
 if(oldCanvas.transform.childCount==0)UnityEngine.Object.DestroyImmediate(oldCanvas);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Temp/WindPopupStyle/setup.txt",report.ToString());}
}
